  // ---- 慣用句：基礎8・標準12・発展8（原作の4問を合わせて）----
  function idi(diff,phrase,answer,wrong,hints,explanation){
    add('idiom',diff,'「'+phrase+'」の意味は何ですか。',answer,wrong,hints,explanation,null,null);
  }
  function idiFill(diff,phrase,answer,wrong,hints,explanation,acc){
    add('idiom',diff,phrase,answer,wrong,hints,explanation,null,acc);
  }
