  // ---- ことわざ・故事成語・四字熟語：基礎8・標準12・発展9（原作の3問を合わせて）----
  function pv(diff,phrase,answer,wrong,hints,explanation,kind){
    add('proverb',diff,(kind||'ことわざ')+'「'+phrase+'」の意味は何ですか。',answer,wrong,hints,explanation,null,null);
  }
