  // ---- つなぎ言葉・指示語：基礎8・標準12・発展8（原作の2問を合わせて）----
  function cj(diff,sentence,answer,wrong,hints,explanation,inp){
    add('conjunction',diff,'□に入る言葉は何ですか。\n「'+sentence+'」',answer,wrong,hints,explanation,null,inp||null);
  }
  cj('basic','朝ごはんを食べた。□、学校へ行った。','それから',['しかし','なぜなら','つまり'],['前の文と、あとの文が、じゅんばんに続いています。','「次に」という意味の言葉をさがします。'],'「それから」は、ことがらが、じゅんばんに続くときに使います。',['それから']);
