  cj('standard','走るのは得意だ。□、泳ぐのは苦手だ。','けれども',['だから','そして','それから'],['「得意」と「苦手」は反対の内容です。','前の文とは、反対のことを言っています。'],'「けれども」は、前の文とは反対のことが続くときに使います。',['けれども','しかし']);
  cj('standard','ねぼうしてしまった。□、ちこくはしなかった。','ところが',['だから','そして','つまり'],['ふつうは、ねぼうすると、どうなるでしょう。','予想と反対のことが起こっています。'],'「ところが」は、前のことから予想されるのとは、ちがうことが起こるときに使います。',['ところが']);
  cj('standard','くだものには、いろいろな種類があります。□、りんごやみかんです。','たとえば',['しかし','だから','それとも'],['前の文の内容を、具体的な例で説明しています。','「例をあげると」という意味の言葉です。'],'「たとえば」は、前に言ったことを、具体的な例を出して説明するときに使います。',['たとえば']);
  cj('standard','ひなたぼっこをした。□、ぽかぽかして気持ちがよかった。','すると',['しかし','なぜなら','それとも'],['前のことをした結果、あとのことが起こりました。','「そうしたところ」という意味の言葉です。'],'「すると」は、前のことのあとに、続けてあることが起こるときに使います。',['すると']);
  cj('standard','そろそろ時間です。□、ほかに質問はありませんか。','ところで',['しかし','だから','それから'],['話の内容が、かわっています。','話題をかえるときに使う言葉です。'],'「ところで」は、話題をかえるときに使います。',['ところで']);
  cj('standard','この本はおもしろい。□、さし絵もきれいだ。','そのうえ',['しかし','だから','つまり'],['前の文に、さらに別のよいところを足しています。','「さらに」と同じような意味の言葉です。'],'「そのうえ」は、前のことに、さらに別のことをつけ足すときに使います。',['そのうえ','さらに']);
  cj('standard','遠足は中止になった。□、雨がふったからだ。','なぜなら',['しかし','それから','ところで'],['あとの文は、前の文の理由を言っています。','「どうして中止になったか」を説明しています。'],'「なぜなら」は、前のことの理由を、あとで説明するときに使います。「～からだ」といっしょに使います。',['なぜなら']);
  cj('standard','春は花がさく。□、夏は海へ行く。','また',['しかし','だから','なぜなら'],['同じようなことを、ならべて言っています。','前の文に、別のことを足しています。'],'「また」は、前のことと、同じようなことをならべたり、足したりするときに使います。',['また']);
  add('conjunction','standard','「ぼくは犬をかっている。それは、とても元気だ。」の「それ」がさしているものは何ですか。','犬',['ぼく','元気','かっていること'],['「それ」は、前の文の中の言葉をさしています。','元気なのは、だれ（何）でしょう。'],'「それ」は、前の文の「犬」をさしています。',null,['いぬ','犬']);
  add('conjunction','standard','「公園の池に、白い鳥がいた。そこには、ほかの鳥もたくさん集まっていた。」の「そこ」がさしているものは何ですか。','公園の池',['白い鳥','公園','ほかの鳥'],['「そこ」は、場所を表す言葉です。','前の文の、場所をさがします。'],'「そこ」は、前の文の「公園の池」をさしています。');

  add('conjunction','advanced','「ぼくは、毎朝走る。これは、健康のためだ。」の「これ」がさしているものは何ですか。','毎朝走ること',['健康','ぼく','朝'],['「これ」は、前の文の内容全体をさしています。','健康のためにしているのは、何でしょう。'],'「これ」は、前の文の「毎朝走ること」をさしています。指示語は、前の文の内容全体をさすこともあります。');
  cj('advanced','手をあらう。□、ごはんを食べる。□、はみがきをする。','次に・最後に',['しかし・つまり','だから・なぜなら','または・それとも'],['ものごとの、じゅんばんを表す言葉をさがします。','「まず」「次に」「最後に」の形で考えます。'],'じゅんばんを表すときは「まず」「次に」「最後に」などを使います。この文では、「次に」「最後に」が入ります。');
  add('conjunction','advanced','前に言ったことを、まとめて言いかえるときに使う言葉は何ですか。','つまり',['たとえば','しかし','それとも'],['前の内容を、短くまとめるときに使います。','「言いかえると」という意味です。'],'「つまり」は、前に言ったことを、まとめたり、言いかえたりするときに使います。',null,['つまり']);
  add('conjunction','advanced','前の文と反対のことを言うときに使う言葉は何ですか。','しかし',['だから','そして','それから'],['「だから」と「しかし」は、反対の関係です。','前の文と、あとの文が、反対の内容のときです。'],'「しかし」は、前の文と反対の内容を続けるときに使います。「だから」は、前のことが理由で、あとのことが起こるときに使います。',null,['しかし']);
  add('conjunction','advanced','どちらか一つをえらぶときに使う言葉は何ですか。','または',['そして','だから','しかし'],['「AまたはB」の形で使います。','「それとも」と同じような意味です。'],'「または」は、二つのうち、どちらか一つをえらぶときに使います。',null,['または','それとも']);
  add('conjunction','advanced','話の内容を、ほかの話題にかえるときに使う言葉は何ですか。','ところで',['つまり','だから','なぜなら'],['前の話と、関係のない話題に、かわるときです。','「それはそうと」という意味です。'],'「ところで」は、話題をかえるときに使います。',null,['ところで']);
